package com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.skill; import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.identity.StableId; public final class TeleportEffectSpec implements EffectSpec{private final StableId effectId;private final int maximumRange;private final MovementPolicies.DestinationPolicy destinationPolicy;public TeleportEffectSpec(StableId id,int range,MovementPolicies.DestinationPolicy policy){if(id==null||policy==null||range<1)throw new IllegalArgumentException("invalid teleport fields");effectId=id;maximumRange=range;destinationPolicy=policy;}@Override public StableId effectId(){return effectId;}@Override public EffectFamily family(){return EffectFamily.MOVEMENT;}@Override public EffectVariantKey variantKey(){return EffectVariantKey.TELEPORT;}public int maximumRange(){return maximumRange;}public MovementPolicies.DestinationPolicy destinationPolicy(){return destinationPolicy;}}
